cc_449_D. Jzzhu and Numbers.code:
import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    a = data[1:1+n]
    MOD = 10**9+7
    BITS = 20
    M = 1 << BITS
    cnt = [0]*M
    for x in a:
        cnt[int(x)] += 1
    # superset sum: f[mask] = number of elements that have all bits of mask set
    for i in range(BITS):
        bit = 1 << i
        for mask in range(M):
            if mask & bit == 0:
                cnt[mask] += cnt[mask | bit]
    pow2 = [1]*(n+1)
    for i in range(1, n+1):
        pow2[i] = pow2[i-1]*2 % MOD
    ans = 0
    for mask in range(M):
        c = cnt[mask]
        term = (pow2[c]-1) % MOD
        if bin(mask).count("1") & 1:
            ans = (ans - term) % MOD
        else:
            ans = (ans + term) % MOD
    print(ans % MOD)

main()

cc_1095_E. Almost Regular Bracket Sequen.code:
import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].strip()
    pref = [0] * (n + 1)
    for i, ch in enumerate(s, 1):
        pref[i] = pref[i - 1] + (1 if ch == '(' else -1)

    total = pref[n]
    # suffix minima of pref
    suff_min = [0] * (n + 2)
    INF = 10**9
    suff_min[n] = pref[n]
    for i in range(n - 1, -1, -1):
        suff_min[i] = pref[i] if pref[i] < suff_min[i + 1] else suff_min[i + 1]

    # prefix minima up to each position
    pref_min = [0] * (n + 1)
    pref_min[0] = pref[0]
    for i in range(1, n + 1):
        pref_min[i] = pref[i] if pref[i] < pref_min[i - 1] else pref_min[i - 1]

    ans = 0
    if total == 2:
        # need to flip '(' to ')'
        for i, ch in enumerate(s, 1):
            if ch == '(':
                if pref_min[i - 1] >= 0 and suff_min[i] >= 2:
                    ans += 1
    elif total == -2:
        # need to flip ')' to '('
        for i, ch in enumerate(s, 1):
            if ch == ')':
                if pref_min[i - 1] >= 0 and suff_min[i] >= -2:
                    ans += 1
    # else ans stays 0
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()

cc_12_B. Correct Solution?.code:
import sys

def minimal_number(s: str) -> str:
    if s == "0":
        return "0"
    digits = sorted(s)
    if digits[0] != '0':
        return ''.join(digits)
    # find first non-zero
    for i, d in enumerate(digits):
        if d != '0':
            # place this digit first, then all zeros, then rest
            first = d
            zeros = digits[:i]
            rest = digits[i+1:]
            return first + ''.join(zeros) + ''.join(rest)
    return ''.join(digits)  # all zeros, shouldn't happen except "0"

def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return
    n = data[0].strip()
    m = data[1].strip()
    correct = minimal_number(n)
    if m == correct:
        sys.stdout.write("OK")
    else:
        sys.stdout.write("WRONG_ANSWER")

if __name__ == "__main__":
    main()

