        pq = [(0, t)]
        while pq:
            d,u = heapq.heappop(pq)
            if d!=dist[u]: continue
            for v in range(1,n+1):
                w = a[u][v]
                if w>0:
                    nd = d + w
                    if nd < dist[v]:
                        dist[v]=nd
                        heapq.heappush(pq,(nd,v))
        prob = [{} for _ in range(n+1)]
        for i in range(1,n+1):
