                p=1.0/len(neigh)
                for j in neigh:
                    prob[i][j]=p
        stack=[s]; reachable=set()
        while stack:
            u=stack.pop()
            if u in reachable: continue
            reachable.add(u)
            for v in prob[u]:
                if v not in reachable:
                    stack.append(v)
        if t not in reachable:
            out_lines.append("impossible")
            continue
        rev_adj=[[] for _ in range(n+1)]
        for i in range(1,n+1):
            for j in prob[i]:
                rev_adj[j].append(i)
        can_to_t=set()
        stack=[t]
        while stack:
            u=stack.pop()
            if u in can_to_t: continue
            can_to_t.add(u)
            for v in rev_adj[u]:
                if v not in can_to_t:
                    stack.append(v)
        bad=False
        for v in reachable:
            if v not in can_to_t:
                bad=True
                break
        if bad:
            out_lines.append("impossible")
            continue
        idx={}
        vars_list=[]
        for v in sorted(reachable):
