            out_lines.append("0.00000000")
            continue
        A=[[0.0]*(m+1) for _ in range(m)]
        for vi,v in enumerate(vars_list):
            A[vi][vi]=1.0
            rhs=0.0
            for j,p in prob[v].items():
                w=a[v][j]
                rhs+=p*w
                if j!=t:
                    A[vi][idx[j]]-=p
            A[vi][m]=rhs
        for col in range(m):
            pivot=col
            while pivot<m and abs(A[pivot][col])<1e-12:
                pivot+=1
            if pivot==m:
                continue
            A[col],A[pivot]=A[pivot],A[col]
            piv=A[col][col]
            for k in range(col,m+1):
