def count_leq(N, k):
    if N < 0:
        return 0
    cnt = 0
    ones = 0
    for pos in range(63, -1, -1):
        if N >> pos & 1:
            # set this bit to 0, choose remaining bits
            rem = pos
            need = k - ones
            if 0 <= need <= rem:
                cnt += C[rem][need]
            ones += 1
            if ones > k:
                break
    else:
        if ones == k:
            cnt += 1
    return cnt

