import sys, math
def solve():
    data = sys.stdin.read().strip().split()
    if not data: 
        return
    it = iter(data)
    k = int(next(it))
    b = [int(next(it)) % (998244353-1) for _ in range(k)]
    n = int(next(it))
    m = int(next(it))
    MOD = 998244353
    MODM1 = MOD-1
    # primitive root
    g = 3

    # discrete log using BSGS
    def dlog(a, target):
        if target == 1:
            return 0
        m_sz = int(math.isqrt(MODM1)) + 1
        table = {}
        cur = 1
        for j in range(m_sz):
            table[cur] = j
            cur = cur * a % MOD
        factor = pow(a, MOD-2, MOD)  # a^{-1}
        factor = pow(factor, m_sz, MOD)  # a^{-m_sz}
        cur = target
        for i in range(m_sz+1):
            if cur in table:
                return i*m_sz + table[cur]
            cur = cur * factor % MOD
        return None

    e_m = dlog(g, m)
    if e_m is None:
        print(-1)
        return

    # matrix exponentiation
    def mat_mul(A, B):
        size = len(A)
        res = [[0]*size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            for k2 in range(size):
                aik = Ai[k2]
                if aik:
                    Bk = B[k2]
                    for j in range(size):
                        res[i][j] = (res[i][j] + aik * Bk[j]) % MODM1
        return res

    def mat_pow(mat, power):
        size = len(mat)
        # identity
        res = [[0]*size for _ in range(size)]
        for i in range(size):
            res[i][i] = 1
        while power:
            if power & 1:
                res = mat_mul(res, mat)
            mat = mat_mul(mat, mat)
            power >>= 1
        return res

    if n == k:
        c = 1 % MODM1
    else:
        # build transition matrix
        T = [[0]*k for _ in range(k)]
        T[0] = b[:]
        for i in range(1, k):
            T[i][i-1] = 1
        P = mat_pow(T, n - k)
        c = P[0][0] % MODM1

    g_val = math.gcd(c, MODM1)
    if c % MODM1 == 0:
        if e_m % MODM1 != 0:
            print(-1)
            return
        x = 0
    else:
        if e_m % g_val != 0:
            print(-1)
            return
        c1 = c // g_val
        mod1 = MODM1 // g_val
        em1 = e_m // g_val
        inv = pow(c1, -1, mod1)
        x = (em1 * inv) % mod1
    f_k = pow(g, x, MOD)
    print(f_k)

