    if line == '#':
        break
    encrypted = line
    candidates = get_candidates(encrypted)
    n = len(candidates)
    print(n)
    if n <= 10:
        for c in candidates:
            print(c)
    else:
        for c in candidates[:5]:
            print(c)
        for c in candidates[-5:]:
            print(c)

