import sys, math

def factorize(n):
    d = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            d[i] = d.get(i, 0) + 1
            n //= i
        i += 1 if i == 2 else 2
    if n > 1:
        d[n] = d.get(n, 0) + 1
    return d

