    sqrt_ops = 0
    exps = list(fac.values())
    while any(e > 1 for e in exps):
        if any(e % 2 == 1 for e in exps):
            mul_ops += 1
        # perform sqrt
        exps = [(e + (e % 2)) // 2 for e in exps]
        sqrt_ops += 1
    print(min_n, mul_ops + sqrt_ops)

