cc_1366_B. Shuffle.code:
import sys
input = sys.stdin.readline

def solve():
    n, x, m = map(int, input().split())
    ops = []
    for _ in range(m):
        l, r = map(int, input().split())
        ops.append((l, r))

    # We need to track the set of positions where the 1 can be after each operation
    # The set can be represented as a union of intervals, but n can be 10^9
    # However, m <= 100, so we can track reachable positions as a set of intervals

    # Start: {x}
    # For each operation i with range [l_i, r_i]:
    #   If current position is in [l_i, r_i], we can move it anywhere in [l_i, r_i]
    #   Otherwise, it stays where it is
    # We want the set of reachable positions after all m operations

    # Represent reachable set as a sorted list of disjoint intervals
    # Initially: [(x, x)]

    # For each operation (l, r):
    #   new_set = union of:
    #     - positions in current set that are NOT in [l, r] (they stay)
    #     - if any position in current set intersects [l, r], then [l, r] becomes reachable

    def union_intervals(intervals):
        if not intervals:
            return []
        intervals.sort()
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1] + 1:
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
            else:
                merged.append((start, end))
        return merged

    def intersects(interval_set, l, r):
        for (a, b) in interval_set:
            if a <= r and b >= l:
                return True
        return False

    def subtract_interval(interval_set, l, r):
        # Remove [l, r] from interval_set
        result = []
        for (a, b) in interval_set:
            if b < l or a > r:
                result.append((a, b))
            else:
                if a < l:
                    result.append((a, l-1))
                if b > r:
                    result.append((r+1, b))
        return result

    current = [(x, x)]

    for (l, r) in ops:
        if intersects(current, l, r):
            # Remove [l,r] portion from current, add [l,r] as new interval
            remaining = subtract_interval(current, l, r)
            new_intervals = remaining + [(l, r)]
            current = union_intervals(new_intervals)
        else:
            # No change
            pass

    # Count total positions
    total = 0
    for (a, b) in current:
        total += b - a + 1

    print(total)

t = int(input())
for _ in range(t):
    solve()

