import sys

def solve():
    it = iter(sys.stdin.read().splitlines())
    out = []
    for line in it:
        if not line:
            continue
        h, w = map(int, line.split())
        if h == 0 and w == 0:
            break
        grid = [list(next(it).rstrip()) for _ in range(h)]
        if grid[0][0] == '#':
            out.append("-1")
            continue
        dp = [[dict() for _ in range(w)] for _ in range(h)]
        dp[0][0][""] = 0  # empty stack, 0 matches
        for i in range(h):
            for j in range(w):
                if grid[i][j] == '#':
                    continue
                cell = grid[i][j]
                cur_states = dp[i][j]
                if not cur_states:
                    continue
                for di, dj in ((0,1),(1,0)):
                    ni, nj = i+di, j+dj
                    if ni>=h or nj>=w or grid[ni][nj]=='#':
                        continue
                    nxt_cell = grid[ni][nj]
                    nxt_dict = dp[ni][nj]
                    for stack, val in cur_states.items():
                        # option: do nothing at next cell (if '.' or choose not to act)
                        ns = stack
                        nv = val
                        key = ns
                        if key not in nxt_dict or nxt_dict[key] < nv:
                            nxt_dict[key] = nv
                        if nxt_cell.islower():
                            # pick jewel
                            ns2 = stack + nxt_cell
                            if ns2 not in nxt_dict or nxt_dict[ns2] < val:
                                nxt_dict[ns2] = val
                        elif nxt_cell.isupper():
                            # place jewel if possible
                            if stack and stack[-1].lower() == nxt_cell.lower():
                                ns2 = stack[:-1]
                                nv2 = val + 1
                                if ns2 not in nxt_dict or nxt_dict[ns2] < nv2:
                                    nxt_dict[ns2] = nv2
        final = dp[h-1][w-1]
        if not final:
            out.append("-1")
        else:
            out.append(str(max(final.values())))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
