import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    p = [0] + list(map(int, data[1:n+1]))
    pos = [0] * (n + 1)
    for i in range(1, n+1):
        pos[p[i]] = i
    swaps = []
    half = n // 2

    def do_swap(i, j):
        swaps.append((i, j))
        a, b = p[i], p[j]
        p[i], p[j] = b, a
        pos[a], pos[b] = j, i

    def valid(i, j):
        return 2 * abs(i - j) >= n

    def move_to(frm, to):
        # move value at frm to position to
        if frm == to:
            return
        if valid(frm, to):
            do_swap(frm, to)
        elif frm <= half:
            # use n as bridge: frm->n, then n->to
            do_swap(frm, n)
            if to != n:
                move_to(n, to)
        else:
            # frm > half, use 1 as bridge
            do_swap(frm, 1)
            if to != 1:
                move_to(1, to)

    for i in range(1, n+1):
        while p[i] != i:
            j = pos[i]
            move_to(j, i)

    print(len(swaps))
    out = []
    for a, b in swaps:
        out.append(f"{a} {b}")
    print('\n'.join(out))

