import sys, collections

def solve():
    data = sys.stdin.read().strip().splitlines()
    it = iter(data)
    out = []
    for line in it:
        if not line:
            continue
        x, y = map(int, line.split())
        if x == 0 and y == 0:
            break
        conn = [[[] for _ in range(2)] for _ in range(x)]
        for _ in range(y):
            a, b = next(it).split()
            pi, Pi = int(a[:-1]), a[-1]
            pj, Pj = int(b[:-1]), b[-1]
            si = 0 if Pi == 'W' else 1
            sj = 0 if Pj == 'W' else 1
            conn[pi][si].append((pj, sj))
            conn[pj][sj].append((pi, si))
        start = []
        for _ in range(x):
            s = next(it).strip()
            start.append("" if s == "-" else s)
        target = []
        for _ in range(x):
            t = next(it).strip()
            target.append("" if t == "-" else t)
        start_t = tuple(start)
        target_t = tuple(target)
        if start_t == target_t:
            out.append("0")
            continue
        q = collections.deque()
        q.append(start_t)
        dist = {start_t: 0}
        found = None
        while q:
            state = q.popleft()
            d = dist[state]
            if d >= 6:
                continue
            lines = list(state)
            for i in range(x):
                li = lines[i]
                if not li:
                    continue
                for side_i in (0, 1):
                    if not conn[i][side_i]:
                        continue
                    maxk = len(li)
                    for k in range(1, maxk + 1):
                        if side_i == 0:
                            sub = li[:k]
                            rem = li[k:]
                        else:
                            sub = li[-k:]
                            rem = li[:-k]
                        for j, side_j in conn[i][side_i]:
                            new_lines = lines.copy()
                            new_lines[i] = rem
                            lj = new_lines[j]
                            # Determine if sub is reversed: reversed if side_i == side_j
                            if side_i == side_j:
                                moved = sub[::-1]
                            else:
                                moved = sub
                            if side_j == 0:
                                new_lines[j] = moved + lj
                            else:
                                new_lines[j] = lj + moved
                            new_state = tuple(new_lines)
                            if new_state in dist:
                                continue
                            nd = d + 1
                            if new_state == target_t:
                                found = nd
                                q.clear()
                                break
                            dist[new_state] = nd
                            q.append(new_state)
                        if found is not None:
                            break
                    if found is not None:
                        break
                if found is not None:
                    break
            if found is not None:
                break
        out.append(str(found if found is not None else dist.get(target_t, -1)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

