import sys
from fractions import Fraction

def compute_angle(tokens):
    if len(tokens) == 1:
        return Fraction(0) if tokens[0] == 'north' else Fraction(90)
    suffix_angle = compute_angle(tokens[1:])
    n = len(tokens) - 1
    delta = Fraction(90, 2 ** n)
    return suffix_angle - delta if tokens[0] == 'north' else suffix_angle + delta

def split_tokens(s):
    tokens = []
    i = 0
    while i < len(s):
        if s.startswith('north', i):
            tokens.append('north')
            i += 5
        else:
            tokens.append('west')
            i += 4
    return tokens

