    for w_str in it:
        w = int(w_str)
        d = int(next(it))
        if w == 0 and d == 0:
            break
        front = [int(next(it)) for _ in range(w)]
        side = [int(next(it)) for _ in range(d)]

        # DP over columns, mask of used rows
        from functools import lru_cache

        @lru_cache(None)
        def dp(col, mask):
            if col == w:
                return 0
            best = dp(col + 1, mask)  # skip matching this column
            for r in range(d):
                if not (mask >> r) & 1 and front[col] == side[r]:
                    cand = front[col] + dp(col + 1, mask | (1 << r))
                    if cand > best:
                        best = cand
            return best

        max_save = dp(0, 0)
        total = sum(front) + sum(side) - max_save
        out_lines.append(str(total))

    sys.stdout.write("\n".join(out_lines))

