        # all gaps odd, first gap gets the extra empties
        extra = n - 2 * k  # can be zero or positive
        first_gap = 1 + extra
    else:
        # one even gap (first), others odd=1
        first_gap = n - 2 * k + 1  # guaranteed even (may be 0)

