    for x in queries:
        if x < a:
            res.append('.')
        else:
            diff = x - a
            if diff % d == 0:
                idx = diff // d
                if idx < k:
                    res.append('X')
                else:
                    res.append('.')
            else:
                res.append('.')
    sys.stdout.write(''.join(res))

