import sys

def count_tatami(h, w):
    if (h * w) % 2 != 0:
        return 0

    grid = [[0] * w for _ in range(h)]
    count = [0]

    def no_cross(r, c):
        # Check if placing a tile created a cross at any junction point
        # A cross occurs at interior point (r,c) if all 4 cells around it have different tile ids
        # Check all 4 corners that touch point (r,c)
        for pr in range(max(0, r-1), min(h-1, r+1)):
            for pc in range(max(0, c-1), min(w-1, c+1)):
                # Check junction at (pr+1, pc+1) - between cells (pr,pc),(pr,pc+1),(pr+1,pc),(pr+1,pc+1)
                if pr+1 < h and pc+1 < w:
                    a = grid[pr][pc]
                    b = grid[pr][pc+1]
                    cc = grid[pr+1][pc]
                    d = grid[pr+1][pc+1]
                    if a != 0 and b != 0 and cc != 0 and d != 0:
                        if a != b and a != cc and b != d and cc != d and a != d and b != cc:
                            return False
        return True

    tile_id = [0]

    def solve(pos):
        while pos < h * w and grid[pos // w][pos % w] != 0:
            pos += 1
        if pos == h * w:
            count[0] += 1
            return

        r, c = pos // w, pos % w
        tile_id[0] += 1
        tid = tile_id[0]

        # Try horizontal placement
        if c + 1 < w and grid[r][c+1] == 0:
            grid[r][c] = tid
            grid[r][c+1] = tid
            if no_cross(r, c) and no_cross(r, c+1):
                solve(pos + 1)
            grid[r][c] = 0
            grid[r][c+1] = 0

        # Try vertical placement
        if r + 1 < h and grid[r+1][c] == 0:
            grid[r][c] = tid
            grid[r+1][c] = tid
            if no_cross(r, c) and no_cross(r+1, c):
                solve(pos + 1)
            grid[r][c] = 0
            grid[r+1][c] = 0

        tile_id[0] -= 1

    solve(0)
    return count[0]

def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        h, w = map(int, parts)
        if h == 0 and w == 0:
            break
        out.append(str(count_tatami(h, w)))
    print("\n".join(out))

if __name__ == "__main__":
    main()

