def fwht(a, invert):
    n = len(a)
    step = 1
    while step < n:
        for i in range(0, n, step * 2):
            for j in range(step):
                u = a[i + j]
                v = a[i + j + step]
                a[i + j] = u + v
                a[i + j + step] = u - v
        step <<= 1
    if invert:
        inv_n = 1.0 / n
        for i in range(n):
            a[i] *= inv_n

