import sys

def polygon_area(poly):
    n = len(poly)
    area = 0.0
    for i in range(n):
        j = (i+1) % n
        area += poly[i][0]*poly[j][1]
        area -= poly[j][0]*poly[i][1]
    return abs(area)/2.0

def clip_polygon_by_halfplane(polygon, a, b, c):
    result = []
    n = len(polygon)
    if n == 0:
        return result
    for i in range(n):
        p1 = polygon[i]
        p2 = polygon[(i+1) % n]
        d1 = a*p1[0] + b*p1[1] + c
        d2 = a*p2[0] + b*p2[1] + c
        if d1 >= 0:
            result.append(p1)
        if (d1 >= 0 and d2 < 0) or (d1 < 0 and d2 >= 0):
            denom = a*(p2[0]-p1[0]) + b*(p2[1]-p1[1])
            if abs(denom) > 1e-12:
                t = -(a*p1[0] + b*p1[1] + c) / denom
                ix = p1[0] + t*(p2[0]-p1[0])
                iy = p1[1] + t*(p2[1]-p1[1])
                result.append((ix, iy))
    return result

def convex_hull(points):
    points = sorted(set(points))
    if len(points) <= 1:
        return points
    lower = []
    for p in points:
        while len(lower) >= 2 and ((lower[-1][0]-lower[-2][0])*(p[1]-lower[-2][1]) - (lower[-1][1]-lower[-2][1])*(p[0]-lower[-2][0])) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and ((upper[-1][0]-upper[-2][0])*(p[1]-upper[-2][1]) - (upper[-1][1]-upper[-2][1])*(p[0]-upper[-2][0])) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def voronoi_cell(island, castles, idx):
    cell = list(island)
    cx, cy = castles[idx]
    for j, (ox, oy) in enumerate(castles):
        if j == idx:
            continue
        a = 2*(cx - ox)
        b = 2*(cy - oy)
        c = ox**2 + oy**2 - cx**2 - cy**2
        cell = clip_polygon_by_halfplane(cell, a, b, c)
        if not cell:
            break
    return cell

def solve():
    data = sys.stdin.read().split()
    idx = 0
    while True:
        N = int(data[idx]); M = int(data[idx+1]); idx += 2
        if N == 0 and M == 0:
            break
        island_pts = []
        for i in range(N):
            x = int(data[idx]); y = int(data[idx+1]); idx += 2
            island_pts.append((x, y))
        castles = []
        for i in range(M):
            x = int(data[idx]); y = int(data[idx+1]); idx += 2
            castles.append((x, y))

        island = convex_hull(island_pts)

        for i in range(M):
            cell = voronoi_cell(island, castles, i)
            area = polygon_area(cell)
            print("%.10f" % area)

solve()

