    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    points = [(int(next(it)), int(next(it))) for _ in range(m)]

    special = set()
    for i in range(m):
        x1, y1 = points[i]
        for j in range(i + 1, m):
            x2, y2 = points[j]
            if y1 == y2:
                continue
            num = y1 * x2 - y2 * x1
            den = y1 - y2
            if den == 0:
                continue
            if num % den != 0:
                continue
            ii = num // den
            if 1 <= ii <= n:
                special.add(ii)

    total = (n - len(special))  # each contributes at least 1
    for i in special:
        cnt = {}
        best = 0
        for x, y in points:
            dx = x - i
            dy = y
            g = math.gcd(dx, dy)
            dx //= g
            dy //= g
            # normalize sign: make dy positive
            if dy < 0:
                dx = -dx
                dy = -dy
            elif dy == 0:
                dx = 1 if dx > 0 else -1
            key = (dx, dy)
            c = cnt.get(key, 0) + 1
            cnt[key] = c
            if c > best:
                best = c
        total += best
    print(total)

