    @lru_cache(maxsize=None)
    def max_result(x):
        if x == 1:
            return 1
        best = x + 1  # take 1 pebble (arrange in x rows of 1)
        # find all divisors b of x where a = x/b > 1, i.e. b < x
        i = 2
