import sys

def balloon_blocks(balloon, light, eye):
    cx, cy, cz, r = balloon
    lx, ly, lz = light
    ex, ey, ez = eye
    vx, vy, vz = ex - lx, ey - ly, ez - lz
    wx, wy, wz = cx - lx, cy - ly, cz - lz
    vv = vx*vx + vy*vy + vz*vz
    t = (vx*wx + vy*wy + vz*wz) / vv
    if t < 0.0:
        dx, dy, dz = cx - lx, cy - ly, cz - lz
    elif t > 1.0:
        dx, dy, dz = cx - ex, cy - ey, cz - ez
    else:
        px, py, pz = lx + t*vx, ly + t*vy, lz + t*vz
        dx, dy, dz = cx - px, cy - py, cz - pz
    return dx*dx + dy*dy + dz*dz < r*r - 1e-9

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    while True:
        N, M, R = int(next(it)), int(next(it)), int(next(it))
        if N == 0 and M == 0 and R == 0:
            break
        balloons = [tuple(map(int, (next(it), next(it), next(it), next(it)))) for _ in range(N)]
        lights, values = [], []
        for _ in range(M):
            tx, ty, tz, tb = int(next(it)), int(next(it)), int(next(it)), int(next(it))
            lights.append((tx, ty, tz))
            values.append(tb)
        ex, ey, ez = int(next(it)), int(next(it)), int(next(it))
        eye = (ex, ey, ez)
        blocker_masks = []
        for j in range(M):
            mask = 0
            for i, bal in enumerate(balloons):
                if balloon_blocks(bal, lights[j], eye):
                    mask |= 1 << i
            blocker_masks.append(mask)
        light_vals = []
        for j in range(M):
            tx, ty, tz = lights[j]
            d2 = (tx-ex)**2 + (ty-ey)**2 + (tz-ez)**2
            light_vals.append(values[j] / d2)
        total_sub = 1 << M
        best = 0.0
        for s in range(total_sub):
            union = 0
            for j in range(M):
                if s & (1 << j):
                    union |= blocker_masks[j]
            if bin(union).count('1') <= R:
                total = 0.0
                for j in range(M):
                    if blocker_masks[j] & ~union == 0:
                        total += light_vals[j]
                if total > best:
                    best = total
        out_lines.append(f"{best:.10f}")
    print("\n".join(out_lines))

if __name__ == "__main__":
    solve()

