        if spf[i] == i:
            step = i
            start = i * i
            for j in range(start, max_k + 1, step):
                if spf[j] == j:
                    spf[j] = i
    # precompute omega factorial prefix sums
    omega_fact = [0] * (max_k + 1)  # total prime factors in k!
    for i in range(2, max_k + 1):
        x = i
        cnt = 0
        while x > 1:
            p = spf[x]
            while x % p == 0:
                x //= p
                cnt += 1
        omega_fact[i] = omega_fact[i - 1] + cnt
    total = sum(omega_fact[k] for k in ks)
    print(total)

