import sys

def rotate_left(s):
    return s[1:] + s[:1] if s else s

def rotate_right(s):
    return s[-1:] + s[:-1] if s else s

def swap_halves(s):
    l = len(s)
    half = l // 2
    if l % 2 == 0:
        return s[half:] + s[:half]
    else:
        return s[half+1:] + s[half] + s[:half]

def inc_digits(s):
    res = []
    for ch in s:
        if '0' <= ch <= '9':
            res.append('0' if ch == '9' else chr(ord(ch) + 1))
        else:
            res.append(ch)
    return ''.join(res)

def dec_digits(s):
    res = []
    for ch in s:
        if '0' <= ch <= '9':
            res.append('9' if ch == '0' else chr(ord(ch) - 1))
        else:
            res.append(ch)
    return ''.join(res)

inverse = {
    'J': rotate_right,
    'C': rotate_left,
    'E': swap_halves,
    'A': lambda s: s[::-1],
    'P': dec_digits,
    'M': inc_digits,
}

