import sys

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    while True:
        try:
            m = int(next(it))
            n = int(next(it))
            d = int(next(it))
        except StopIteration:
            break
        if m == 0 and n == 0 and d == 0:
            break
        N = m * n
        init = []
        for _ in range(n):
            for _ in range(m):
                init.append(int(next(it)))
        # precompute toggle masks for each variable (cell)
        toggle_masks = [0] * N
        for r in range(n):
            for c in range(m):
                idx = r * m + c
                mask = 1 << idx  # itself
                # cells at Manhattan distance d
                for dr in range(-d, d + 1):
                    dc = d - abs(dr)
                    for sign in (-1, 1):
                        nr = r + dr
                        nc = c + sign * dc
                        if 0 <= nr < n and 0 <= nc < m:
                            mask |= 1 << (nr * m + nc)
                # when dc == 0 we added twice same cell, fine
                toggle_masks[idx] = mask
        # build equation rows: for each cell i, which variables affect it
        rows = [0] * N
        rhs = init[:]  # copy
        for var in range(N):
            mask = toggle_masks[var]
            msk = mask
            while msk:
                lsb = msk & -msk
                i = (lsb.bit_length() - 1)
                rows[i] |= 1 << var
                msk ^= lsb
        # Gaussian elimination over GF(2)
        rank = 0
        for col in range(N):
            pivot = -1
            for r in range(rank, N):
                if (rows[r] >> col) & 1:
                    pivot = r
                    break
            if pivot == -1:
                continue
            rows[rank], rows[pivot] = rows[pivot], rows[rank]
            rhs[rank], rhs[pivot] = rhs[pivot], rhs[rank]
            for r in range(N):
                if r != rank and ((rows[r] >> col) & 1):
                    rows[r] ^= rows[rank]
                    rhs[r] ^= rhs[rank]
            rank += 1
        consistent = all(rhs[i] == 0 for i in range(rank, N))
        out_lines.append('1' if consistent else '0')
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()

