import sys

MOD = 1000000007

s = sys.stdin.readline().strip()
n = len(s)

def possible_bombs(ch):
    if ch == '*':
        return (1,)
    if ch == '?':
        return (0, 1)
    # digit
    return (0,)

# initial states after processing position 0
dp = {}
for b0 in possible_bombs(s[0]):  # bomb at position 0
    # if it's a digit, bomb must be 0 (already ensured)
    dp[(b0, 0)] = (dp.get((b0, 0), 0) + 1) % MOD  # (bomb_i, bomb_{i-1}) where bomb_{-1}=0

for i in range(1, n):
    ndp = {}
    ch_prev = s[i-1]
    ch_cur = s[i]
    for (prev1, prev2), cnt in dp.items():  # prev1 = bomb_{i-1}, prev2 = bomb_{i-2}
        # validate cell i-1 now
        if ch_prev == '*':
            if prev1 != 1:
                continue
        elif ch_prev in '012':
            if prev1 != 0:
                continue
            # digit must equal bombs at i-2 and i (prev2 + cur)
            # we will check after choosing cur bomb
        else:  # '?'
            # if we later set bomb, it's allowed; if we set digit later, will be checked then
            pass

        for cur in possible_bombs(ch_cur):  # bomb_i
            # check digit constraint for i-1 if it's a digit
            if ch_prev in '012':
                if (prev2 + cur) != int(ch_prev):
                    continue
            # also if ch_prev == '?' and we decided it was a bomb earlier (prev1==1) that's fine,
            # if it was a digit earlier (prev1==0) we need to ensure its digit matches prev2+cur.
            if ch_prev == '?' and prev1 == 0:
                # we don't know which digit was written, but it must be consistent with neighbors
                # So the digit would be prev2+cur, which must be 0,1,2 -> always true
                # No extra restriction
                pass
            # also ensure that if ch_prev == '?' and prev1 == 1, it's bomb, no digit check
            # all good
            key = (cur, prev1)
            ndp[key] = (ndp.get(key, 0) + cnt) % MOD
    dp = ndp

# after processing all positions, validate last cell (index n-1)
ans = 0
last_ch = s[-1]
for (prev1, prev2), cnt in dp.items():  # prev1 = bomb_{n-1}, prev2 = bomb_{n-2}
    if last_ch == '*':
        if prev1 != 1:
            continue
    elif last_ch in '012':
        if prev1 != 0:
            continue
        if (prev2 + 0) != int(last_ch):  # right neighbor absent -> 0
            continue
    else:  # '?'
        # could be bomb or digit
        # if bomb
        if prev1 == 1:
            ans = (ans + cnt) % MOD
        # if digit
        if prev1 == 0:
            # digit would be prev2 (since right neighbor 0)
            # any value 0..2 allowed, no further restriction
            ans = (ans + cnt) % MOD
        continue
    ans = (ans + cnt) % MOD

print(ans % MOD)

