import sys

def tokenize(s):
    i = 0
    n = len(s)
    tokens = []
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(('NUM', int(s[i:j])))
            i = j
        elif 'a' <= c <= 'z':
            tokens.append(('VAR', c))
            i += 1
        elif c in '+-^()':
            tokens.append((c, c))
            i += 1
        else:
            i += 1
    tokens.append(('EOF', None))
    return tokens

def add_poly(p1, p2, sign=1):
    res = p1.copy()
    for m, c in p2.items():
        res[m] = res.get(m, 0) + sign * c
        if res[m] == 0:
            del res[m]
    return res

def mul_poly(p1, p2):
    res = {}
    for m1, c1 in p1.items():
        for m2, c2 in p2.items():
            exp = tuple(m1[i] + m2[i] for i in range(26))
            coeff = c1 * c2
            res[exp] = res.get(exp, 0) + coeff
            if res[exp] == 0:
                del res[exp]
    return res

class Parser:
    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

    def cur(self):
        return self.toks[self.pos][0]

    def eat(self, typ=None):
        cur = self.toks[self.pos]
        if typ and cur[0] != typ:
            raise ValueError
        self.pos += 1
        return cur

    def parse(self):
        return self.expr()

    def expr(self):
        poly = self.term()
        while self.cur() in ('+', '-'):
            op = self.eat()[0]
            right = self.term()
            poly = add_poly(poly, right, 1 if op == '+' else -1)
        return poly

    def term(self):
        poly = self.factor()
        while self.cur() in ('NUM', 'VAR', '('):
            right = self.factor()
            poly = mul_poly(poly, right)
        return poly

    def factor(self):
        tok = self.toks[self.pos]
        if tok[0] == 'NUM':
            self.eat('NUM')
            return { (0,)*26: tok[1] }
        elif tok[0] == 'VAR':
            self.eat('VAR')
            exp = [0]*26
            idx = ord(tok[1]) - 97
            exp[idx] = 1
            if self.cur() == '^':
                self.eat('^')
                num = self.eat('NUM')[1]
                exp[idx] = num
            return { tuple(exp): 1 }
        elif tok[0] == '(':
            self.eat('(')
            poly = self.expr()
            self.eat(')')
            return poly
        else:
            raise ValueError

def parse_expr(s):
    return Parser(tokenize(s)).parse()

def main():
    out = []
    lines = sys.stdin.read().splitlines()
    i = 0
    while i < len(lines):
        if lines[i] == '.':
            break
        correct = parse_expr(lines[i])
        i += 1
        while i < len(lines) and lines[i] != '.':
            student = parse_expr(lines[i])
            out.append('yes' if student == correct else 'no')
            i += 1
        out.append('.')
        i += 1
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    main()

