def overlap_area(r1, r2, d):
    if d >= r1 + r2: return 0.0
    if d <= abs(r1 - r2): return math.pi * min(r1, r2) ** 2
    r1sq, r2sq, dsq = r1*r1, r2*r2, d*d
    alpha = math.acos((dsq + r1sq - r2sq) / (2*d*r1))
    beta  = math.acos((dsq + r2sq - r1sq) / (2*d*r2))
    return r1sq*alpha + r2sq*beta - 0.5*math.sqrt((-d+r1+r2)*(d+r1-r2)*(d-r1+r2)*(d+r1+r2))

def find_distance(r1, r2, target):
    if target < -1e-9: return None
    max_ov = math.pi * min(r1,r2)**2
    if target > max_ov + 1e-9: return None
    if target < 1e-12: return r1 + r2
    low, high = 0.0, r1 + r2
    for _ in range(100):
        mid = (low + high) / 2
        if overlap_area(r1, r2, mid) > target: low = mid
        else: high = mid
    return (low + high) / 2

def fits(x, y, r, UW, UH):
    return x - r >= -1e-4 and x + r <= UW + 1e-4 and y - r >= -1e-4 and y + r <= UH + 1e-4

def solve():
    for line in sys.stdin:
        if not line.strip(): continue
        parts = list(map(int, line.split()))
        UW, UH, a, b, inter = parts
        if UW == UH == a == b == inter == 0: break
        if inter > min(a, b):
            print("impossible"); continue
        rA = math.sqrt(a / math.pi) if a > 0 else 0.0
        rB = math.sqrt(b / math.pi) if b > 0 else 0.0
        d = find_distance(rA, rB, inter)
        if d is None:
            print("impossible"); continue
        placed = False
        for (ra, rb, swapped) in [(rA, rB, False), (rB, rA, True)]:
            for y in [ra, UH/2, UH - ra]:
                if not (ra - 1e-4 <= y <= UH - ra + 1e-4): continue
                x1 = ra
                if not fits(x1, y, ra, UW, UH): x1 = UW - ra
                if not fits(x1, y, ra, UW, UH): continue
                x2 = x1 + d
                y2 = y
                if not fits(x2, y2, rb, UW, UH):
                    x2 = x1 - d; y2 = y
                if not fits(x2, y2, rb, UW, UH):
                    x2 = x1; y2 = y + d
                if not fits(x2, y2, rb, UW, UH):
                    x2 = x1; y2 = y - d
                if not fits(x2, y2, rb, UW, UH):
                    x2 = UW - rb; y2 = rb
                    if abs(math.hypot(x2-x1,y2-y) - d) > 1e-6:
                        continue
                if not fits(x2, y2, rb, UW, UH): continue
                if swapped:
                    print(f"{x2:.13f} {y2:.13f} {rA:.13f} {x1:.13f} {y:.13f} {rB:.13f}")
                else:
                    print(f"{x1:.13f} {y:.13f} {ra:.13f} {x2:.13f} {y2:.13f} {rb:.13f}")
                placed = True; break
            if placed: break
        if not placed:
            print("impossible")

solve()

