import sys, heapq

def solve() -> None:
    data = list(map(int, sys.stdin.read().split()))
    it = iter(data)
    N = next(it); M = next(it); K = next(it); S = next(it)
    P = next(it); Q = next(it)
    zombie = [False]*(N+1)
    zombie_nodes = []
    for _ in range(K):
        c = next(it)
        zombie[c] = True
        zombie_nodes.append(c)
    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        a = next(it); b = next(it)
        adj[a].append(b)
        adj[b].append(a)

    # multi-source BFS for distances from zombie towns
    from collections import deque
    INF = 10**9
    dist = [INF]*(N+1)
    dq = deque()
    for z in zombie_nodes:
        dist[z] = 0
        dq.append(z)
    while dq:
        u = dq.popleft()
        if dist[u] == S:  # no need to expand further
            continue
        nd = dist[u] + 1
        for v in adj[u]:
            if dist[v] > nd:
                dist[v] = nd
                dq.append(v)

    dangerous = [False]*(N+1)
    for i in range(1, N+1):
        if not zombie[i] and dist[i] <= S:
            dangerous[i] = True

    cost = [0]*(N+1)
    for i in range(1, N+1):
        if i == N or i == 1:
            cost[i] = 0
        elif dangerous[i]:
            cost[i] = Q
        else:
            cost[i] = P

    # Dijkstra
    dist2 = [10**30]*(N+1)
    dist2[1] = 0
    heap = [(0,1)]
    while heap:
        d,u = heapq.heappop(heap)
        if d!=dist2[u]:
            continue
        if u==N:
            break
        for v in adj[u]:
            if zombie[v]:
                continue
            nd = d + cost[v]
            if nd < dist2[v]:
                dist2[v] = nd
                heapq.heappush(heap,(nd,v))
    print(dist2[N])

if __name__ == "__main__":
    solve()

