import sys

def count_ways(N: int) -> int:
    cnt = 0
    k = 2
    while k * (k + 1) // 2 <= N:
        remainder = N - k * (k - 1) // 2
        if remainder > 0 and remainder % k == 0:
            cnt += 1
        k += 1
    return cnt

def main():
    out_lines = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n = int(line)
        if n == 0:
            break
        out_lines.append(str(count_ways(n)))
    sys.stdout.write("\n".join(out_lines))

