import sys, math

def pow_limit(base, exp, limit):
    res = 1
    b = base
    while exp:
        if exp & 1:
            res *= b
            if res > limit:
                return limit + 1
        exp >>= 1
        if exp:
            b *= b
            if b > limit:
                b = limit + 1
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, l, r = map(int, data)
    if n == 1:
        print(r - l + 1)
        return
    if n == 2:
        m = r - l + 1
        print(m * (m - 1))
        return
    total = 0
    k = 2
    while True:
        p = pow_limit(k, n - 1, r)
        if p > r:
            break
        max_b = r // p
        if max_b >= l:
            total += 2 * (max_b - l + 1)
        k += 1
    print(total)

