    comp = [-1]*N
    def rdfs(v, cid):
        comp[v]=cid
        for to in rg[v]:
            if comp[to]==-1:
                rdfs(to,cid)
    cid=0
    for v in reversed(order):
        if comp[v]==-1:
            rdfs(v,cid)
            cid+=1
    C = cid  # number of components

    # build component graph
    succ = [-1]*C
    children = [[] for _ in range(C)]
    for u in range(N):
        cu = comp[u]
        v = out[u]
        if v!=-1:
            cv = comp[v]
            if cu!=cv:
                succ[cu]=cv
                children[cv].append(cu)

    # DP f1 for each component
    f1 = [0]*C
    sys.setrecursionlimit(1000000)
    def compute(u):
        prod = 1
        for ch in children[u]:
            compute(ch)
            prod = prod * f1[ch] % MOD
        f1[u] = (1 + prod) % MOD
    # roots are components with succ==-1
    ans = 1
    for u in range(C):
        if succ[u]==-1:
            compute(u)
            ans = ans * f1[u] % MOD
    print(ans)

if __name__ == "__main__":
    main()

