cc_1353_E. K-periodic Garland.code:
import sys

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    t = int(next(it))
    out = []
    for _ in range(t):
        n = int(next(it)); k = int(next(it))
        s = next(it).strip()
        total_ones = s.count('1')
        cnt = [0]*k
        for idx,ch in enumerate(s):
            if ch=='1':
                cnt[idx%k] += 1
        best = total_ones  # all zeros case
        for i in range(k):
            if i >= n:
                continue
            length = (n - i - 1)//k + 1
            flips = length + total_ones - 2*cnt[i]
            if flips < best:
                best = flips
        out.append(str(best))
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    solve()
